## Reference Implementations (Python & Java)

```python
# Quick QPS, Peak QPS, and 5-year Storage Estimator (Python)
def estimate_system(dau: int, reqs_per_user_day: int, bytes_per_write: int, write_ratio: float = 0.1):
    avg_qps = (dau * reqs_per_user_day) / 86_400
    peak_qps = avg_qps * 3
    daily_write_bytes = dau * reqs_per_user_day * write_ratio * bytes_per_write
    five_year_tb = (daily_write_bytes * 365 * 5) / (1024 ** 4)
    return {"avg_qps": round(avg_qps, 1), "peak_qps": round(peak_qps, 1), "storage_5yr_tb": round(five_year_tb, 2)}
```

```java
// Quick QPS and 5-year Storage Estimator (Java)
public static Map<String, Double> estimate(long dau, int reqsPerDay, int bytesPerWrite, double writeRatio) {
    double avgQps = (dau * (double) reqsPerDay) / 86_400.0;
    double peakQps = avgQps * 3.0;
    double dailyBytes = dau * (double) reqsPerDay * writeRatio * bytesPerWrite;
    double fiveYearTb = (dailyBytes * 365.0 * 5.0) / Math.pow(1024, 4);
    return Map.of("avgQps", avgQps, "peakQps", peakQps, "storage5YrTb", fiveYearTb);
}
```
